import {useState} from 'react'
import useRequest from '../use-request'
import {COPILOT_MODELS_ROUTE} from '../../routes'

import type {Filters, Model} from '../../types/usage'

type useModelsDataParams = {
  filters: Filters
}

function useModelsData({filters}: useModelsDataParams) {
  const [modelsData, setModelsData] = useState<Model[]>([])

  useRequest({
    route: COPILOT_MODELS_ROUTE,
    noop: !filters.searchQuery?.includes('model:'), // Only fetch when we have a model filter
    onSuccess: response => {
      setModelsData(response.data.models)
    },
  })
  return {modelsData}
}

export default useModelsData
